import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

good_numbers = set()
limit = 20 # Test pairs up to y=20

for x in range(2, limit):
    for y in range(x + 1, limit + 1):
        if gcd(x, y) > 1:
            m = x**2 + y**2
            good_numbers.add(m)

# Sort and find the 20th smallest
sorted_good_numbers = sorted(list(good_numbers))

# Check if we found at least 20
if len(sorted_good_numbers) >= 20:
    print(f"Found {len(sorted_good_numbers)} unique good numbers up to limit {limit}.")
    print(f"The 20th smallest good number is: {sorted_good_numbers[19]}")
else:
    print(f"Only found {len(sorted_good_numbers)} unique good numbers up to limit {limit}. Need to increase limit.")
